//! rosetta-pricing — list-price-equivalent USD for canonical usage records
//! (docs/ARCHITECTURE.md §4.1.3).
//!
//! A static catalog generated by `tools/pricing` from pinned genai-prices data
//! plus a cited overlay, and an exact integer calculator. Pricing does no IO,
//! reads no clock, and never allocates for an already-lowercase model id.
//! Adapters never call it: the store prices usage records inside the hourly
//! rollup, and the server prices one response at read time.

mod catalog;
// Generator output is committed byte-exact (`tools/pricing generate --check`).
#[rustfmt::skip]
mod generated;

pub use catalog::{
    Constraint, Model, Period, PicoUsd, Prices, Rate, RouteRule, Source, TierRule, TierStep,
};
use std::sync::LazyLock;

use rosetta_core::{ServiceTier, TokenSnapshot, UsageScope};

/// Identity of the compiled catalog: upstream revision, overlay hash and
/// generator version.
pub const CATALOG_VERSION: &str = generated::CATALOG_VERSION;

/// Revision of [`quote`]'s arithmetic. Bump it with any change to what a
/// record costs under an unchanged catalog.
const CALCULATOR_REVISION: u32 = 1;

/// Everything a stored cost depends on: the catalog and the calculator. The
/// projection stamps the version its rollup costs were computed with and
/// re-prices when this changes.
pub fn pricing_version() -> &'static str {
    static VERSION: LazyLock<String> =
        LazyLock::new(|| format!("{CATALOG_VERSION}+calc{CALCULATOR_REVISION}"));
    &VERSION
}

const DAY_MS: i64 = 86_400_000;
const PICO_PER_MICRO: i128 = 1_000_000;

pub fn models() -> &'static [Model] {
    generated::MODELS
}

pub fn sources() -> &'static [Source] {
    generated::SOURCES
}

pub fn tier_rules() -> &'static [TierRule] {
    generated::TIER_RULES
}

pub fn route_rules() -> &'static [RouteRule] {
    generated::ROUTE_RULES
}

/// One usage record to price. Counts are the six mutually exclusive token
/// buckets plus web searches; an unreported count is zero here because the
/// record never claimed it.
#[derive(Debug, Clone, Copy, Default)]
pub struct Request<'a> {
    pub model: &'a str,
    pub at_ms: Option<i64>,
    pub scope: UsageScope,
    pub input: i64,
    pub output: i64,
    pub cache_read: i64,
    pub cache_write: i64,
    pub cache_write_1h: i64,
    pub thinking: i64,
    pub web_searches: i64,
    pub service_tier: Option<ServiceTier>,
    pub route: Option<&'a str>,
}

impl<'a> Request<'a> {
    pub fn from_usage(model: &'a str, at_ms: Option<i64>, usage: &'a TokenSnapshot) -> Self {
        Self {
            model,
            at_ms,
            scope: usage.scope,
            input: usage.input.unwrap_or(0),
            output: usage.output.unwrap_or(0),
            cache_read: usage.cache_read.unwrap_or(0),
            cache_write: usage.cache_write.unwrap_or(0),
            cache_write_1h: usage.cache_write_1h.unwrap_or(0),
            thinking: usage.thinking.unwrap_or(0),
            web_searches: usage.web_searches.unwrap_or(0),
            service_tier: usage.service_tier,
            route: usage.route.as_deref(),
        }
    }

    /// What long-context tiers compare: every prompt token, cached or not.
    pub fn prompt_tokens(&self) -> i64 {
        self.input
            .saturating_add(self.cache_read)
            .saturating_add(self.cache_write)
            .saturating_add(self.cache_write_1h)
    }
}

/// The unit a missing rate belongs to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Unit {
    Input,
    Output,
    WebSearch,
}

/// Why a record has no list price. Unpriced is never zero dollars.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Unpriced {
    /// No catalog id or explicit alias equals the model after removing a
    /// date stamp, context tag or vendor prefix.
    UnknownModel,
    /// The record has no timestamp and the model's price changed over time.
    AmbiguousTime,
    /// A non-standard service tier without a cited overlay rule.
    UnsupportedTier(ServiceTier),
    /// A route qualifier (`provider/qualifier`) without a cited premium.
    UnsupportedRoute,
    /// A non-zero count whose unit (or every ancestor) has no rate.
    MissingRate(Unit),
    /// An aggregate sample whose prompt tokens exceed a tier start: the
    /// per-request tiers cannot be recovered from a total.
    AggregateAboveTier,
    /// An aggregate sample of a model with a per-request fee.
    AggregateRequestFee,
    NegativeCount,
    Overflow,
}

impl Unpriced {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::UnknownModel => "unknown_model",
            Self::AmbiguousTime => "ambiguous_time",
            Self::UnsupportedTier(_) => "unsupported_tier",
            Self::UnsupportedRoute => "unsupported_route",
            Self::MissingRate(_) => "missing_rate",
            Self::AggregateAboveTier => "aggregate_above_tier",
            Self::AggregateRequestFee => "aggregate_request_fee",
            Self::NegativeCount => "negative_count",
            Self::Overflow => "overflow",
        }
    }
}

/// A priced record.
#[derive(Debug, Clone, Copy)]
pub struct Quote {
    pub pico_usd: PicoUsd,
    pub model: &'static Model,
    /// Index of the price period in force at the record's timestamp.
    pub period: usize,
    /// The prompt crossed a long-context tier start.
    pub long_context: bool,
}

/// List-price-equivalent cost of one record in pico-USD.
pub fn list_cost(request: &Request<'_>) -> Result<PicoUsd, Unpriced> {
    quote(request).map(|quote| quote.pico_usd)
}

pub fn quote(request: &Request<'_>) -> Result<Quote, Unpriced> {
    let counts = [
        request.input,
        request.output,
        request.cache_read,
        request.cache_write,
        request.cache_write_1h,
        request.thinking,
        request.web_searches,
    ];
    if counts.iter().any(|count| *count < 0) {
        return Err(Unpriced::NegativeCount);
    }
    let model = resolve(request.model).ok_or(Unpriced::UnknownModel)?;
    let (period, selected) = select_period(model, request.at_ms)?;
    let prices = &selected.prices;
    let prompt = request.prompt_tokens();
    let first_tier = lowest_tier_start(prices);
    let long_context = first_tier.is_some_and(|start| prompt > start);
    if request.scope == UsageScope::Aggregate {
        if long_context {
            return Err(Unpriced::AggregateAboveTier);
        }
        if prices.request.is_some() {
            return Err(Unpriced::AggregateRequestFee);
        }
    }

    // genai-prices decomposition: a child unit without a rate is charged at
    // its nearest priced ancestor's rate.
    let input = prices.input;
    let cache_read = prices.cache_read.or(input);
    let cache_write = prices.cache_write.or(input);
    let cache_write_1h = prices.cache_write_1h.or(prices.cache_write).or(input);
    let output = prices.output;
    let reasoning = prices.output_reasoning.or(output);

    let mut tokens: i128 = 0;
    for (count, rate, unit) in [
        (request.input, input, Unit::Input),
        (request.cache_read, cache_read, Unit::Input),
        (request.cache_write, cache_write, Unit::Input),
        (request.cache_write_1h, cache_write_1h, Unit::Input),
        (request.output, output, Unit::Output),
        (request.thinking, reasoning, Unit::Output),
    ] {
        if count == 0 {
            continue;
        }
        let rate = rate.ok_or(Unpriced::MissingRate(unit))?;
        tokens += i128::from(count) * i128::from(rate.at(prompt));
    }

    // Tier and route rules scale token rates only, as their overlay sources
    // cite; per-call search fees and per-request fees stay flat.
    let (mut numerator, mut denominator) = (1_i128, 1_i128);
    match request.service_tier {
        None | Some(ServiceTier::Standard) => {}
        Some(tier) => {
            let rule = tier_rule(model, tier).ok_or(Unpriced::UnsupportedTier(tier))?;
            numerator *= i128::from(rule.numerator);
            denominator *= i128::from(rule.denominator);
        }
    }
    if let Some(route) = request.route
        && route.contains('/')
    {
        let rule = route_rule(model, route).ok_or(Unpriced::UnsupportedRoute)?;
        numerator *= i128::from(rule.numerator);
        denominator *= i128::from(rule.denominator);
    }
    let mut total = if denominator != 1 || numerator != 1 {
        (tokens * numerator + denominator / 2) / denominator
    } else {
        tokens
    };
    if request.web_searches > 0 {
        let per_call = prices
            .web_search_call
            .ok_or(Unpriced::MissingRate(Unit::WebSearch))?;
        total += i128::from(request.web_searches) * i128::from(per_call);
    }
    if let Some(fee) = prices.request {
        total += i128::from(fee);
    }
    let pico_usd = PicoUsd::try_from(total).map_err(|_| Unpriced::Overflow)?;
    Ok(Quote {
        pico_usd,
        model,
        period,
        long_context,
    })
}

impl Rate {
    /// The rate for a request of `prompt` tokens: the highest tier whose start
    /// the prompt strictly exceeds, else the base rate.
    pub fn at(&self, prompt: i64) -> PicoUsd {
        self.tiers
            .iter()
            .rev()
            .find(|step| prompt > step.start)
            .map_or(self.base, |step| step.rate)
    }
}

impl Constraint {
    pub fn active(self, at_ms: i64) -> bool {
        match self {
            Self::Always => true,
            Self::FromDay(day) => at_ms.div_euclid(DAY_MS) >= i64::from(day),
            Self::TimeOfDay { start_s, end_s } => {
                let second = at_ms.div_euclid(1_000).rem_euclid(86_400);
                let (start, end) = (i64::from(start_s), i64::from(end_s));
                if end < start {
                    second >= start || second < end
                } else {
                    start <= second && second < end
                }
            }
        }
    }
}

fn select_period(
    model: &'static Model,
    at_ms: Option<i64>,
) -> Result<(usize, &'static Period), Unpriced> {
    match model.periods {
        [] => Err(Unpriced::UnknownModel),
        [only] => Ok((0, only)),
        periods => {
            let at_ms = at_ms.ok_or(Unpriced::AmbiguousTime)?;
            Ok(periods
                .iter()
                .enumerate()
                .rev()
                .find(|(_, period)| period.constraint.active(at_ms))
                .unwrap_or((0, &periods[0])))
        }
    }
}

fn lowest_tier_start(prices: &Prices) -> Option<i64> {
    [
        prices.input,
        prices.output,
        prices.cache_read,
        prices.cache_write,
        prices.cache_write_1h,
        prices.output_reasoning,
    ]
    .into_iter()
    .flatten()
    .filter_map(|rate| rate.tiers.first().map(|step| step.start))
    .min()
}

fn tier_rule(model: &Model, tier: ServiceTier) -> Option<&'static TierRule> {
    let rules = generated::TIER_RULES;
    rules
        .iter()
        .find(|rule| {
            rule.provider == model.provider && rule.tier == tier && rule.model == Some(model.id)
        })
        .or_else(|| {
            rules.iter().find(|rule| {
                rule.provider == model.provider && rule.tier == tier && rule.model.is_none()
            })
        })
}

fn route_rule(model: &Model, route: &str) -> Option<&'static RouteRule> {
    generated::ROUTE_RULES.iter().find(|rule| {
        rule.route == route
            && rule.provider == model.provider
            && (rule.models.is_empty() || rule.models.contains(&model.id))
    })
}

/// Exact model resolution. The native id must equal a catalog id or an
/// explicit alias once a context tag (`[1m]`), a version suffix (`@…`), a
/// vendor prefix (`anthropic/`) and a trailing date stamp (`-YYYYMMDD`,
/// `-YYYY-MM-DD`) are removed. Prefix matching is never used: it would price
/// `claude-opus-5-5` as `claude-opus-5`.
pub fn resolve(model: &str) -> Option<&'static Model> {
    let trimmed = model.trim();
    let lowered;
    let base = if trimmed.bytes().any(|byte| byte.is_ascii_uppercase()) {
        lowered = trimmed.to_ascii_lowercase();
        lowered.as_str()
    } else {
        trimmed
    };
    let tagless = strip_version_suffix(strip_context_tag(base));
    let vendorless = strip_vendor(tagless);
    [
        base,
        tagless,
        vendorless,
        strip_date(tagless),
        strip_date(vendorless),
    ]
    .into_iter()
    .find_map(lookup)
}

fn lookup(candidate: &str) -> Option<&'static Model> {
    let aliases = generated::ALIASES;
    aliases
        .binary_search_by(|(alias, _)| (*alias).cmp(candidate))
        .ok()
        .map(|index| &generated::MODELS[usize::from(aliases[index].1)])
}

fn strip_context_tag(model: &str) -> &str {
    match (model.strip_suffix(']'), model.rfind('[')) {
        (Some(_), Some(open)) if open > 0 => &model[..open],
        _ => model,
    }
}

fn strip_version_suffix(model: &str) -> &str {
    model.split_once('@').map_or(model, |(head, _)| head)
}

fn strip_vendor(model: &str) -> &str {
    model.rsplit_once('/').map_or(model, |(_, tail)| tail)
}

fn strip_date(model: &str) -> &str {
    let bytes = model.as_bytes();
    let digits = |range: std::ops::Range<usize>| bytes[range].iter().all(u8::is_ascii_digit);
    let len = bytes.len();
    // -YYYYMMDD
    if len > 9 && bytes[len - 9] == b'-' && digits(len - 8..len) {
        return &model[..len - 9];
    }
    // -YYYY-MM-DD
    if len > 11
        && bytes[len - 11] == b'-'
        && digits(len - 10..len - 6)
        && bytes[len - 6] == b'-'
        && digits(len - 5..len - 3)
        && bytes[len - 3] == b'-'
        && digits(len - 2..len)
    {
        return &model[..len - 11];
    }
    model
}

/// Convert pico-USD to integer micro-USD for the wire, rounding half away
/// from zero once at the boundary.
pub fn pico_to_micro(pico: PicoUsd) -> i64 {
    let pico = i128::from(pico);
    let half = PICO_PER_MICRO / 2;
    let rounded = if pico >= 0 {
        (pico + half) / PICO_PER_MICRO
    } else {
        (pico - half) / PICO_PER_MICRO
    };
    i64::try_from(rounded).unwrap_or(if pico >= 0 { i64::MAX } else { i64::MIN })
}

